(function(){'use strict';const F=Forest,$=id=>document.getElementById(id);let scene,selected=-1,buildType=-1,manualPause=false,soundOn=false,audio,toastTimer,screenStack=['home'];const formNames=[['弓箭塔','連射塔','狙擊塔','翠葉連射塔','月影狙擊塔'],['火焰塔','爆炎塔','灼燒塔','熾焰爆炎塔','煉火灼燒塔']];const game=()=>scene.model;const portrait=()=>matchMedia('(orientation:portrait)').matches;
function pauseState(){if(!scene)return;game().paused=manualPause||portrait()||document.hidden||screenStack.at(-1)!=='battle';$('pauseBtn').textContent=manualPause?'▸':'Ⅱ';$('pauseBtn').setAttribute('aria-label',manualPause?'繼續遊戲':'暫停遊戲');}
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,2600);}
function sound(kind){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),gain=audio.createGain();o.connect(gain);gain.connect(audio.destination);o.type=kind==='fire'?'triangle':'sine';o.frequency.setValueAtTime({arrow:680,fire:150,leak:110,upgrade:440}[kind]||440,audio.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='arrow'?390:70,audio.currentTime+.12);gain.gain.setValueAtTime(.025,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.14);o.start();o.stop(audio.currentTime+.15);}catch{}}
function open(title,html,kind='menu'){if(screenStack.at(-1)!=='battle'&&screenStack.at(-1)!=='home')screenStack.pop();screenStack.push(kind);$('modalTitle').textContent=title;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal();pauseState();$('closeModal').focus();}
function close(){if($('modal').open)$('modal').close();if(screenStack.length>1)screenStack.pop();pauseState();}
function home(){close();screenStack=['home'];scene.playing=false;$('home').hidden=false;for(const id of ['hud','status','battleFoot','tray','platforms'])$(id).hidden=true;document.body.classList.remove('tray-open');pauseState();}
function start(fresh=true){close();if(fresh)scene.reset();screenStack=['battle'];manualPause=false;selected=-1;buildType=-1;scene.playing=true;$('home').hidden=true;for(const id of ['hud','status','battleFoot','platforms'])$(id).hidden=false;hideTray();pauseState();hud();}
function hideTray(){selected=-1;buildType=-1;scene.select(-1);$('tray').hidden=true;document.body.classList.remove('tray-open');}
function select(i){selected=i;buildType=-1;scene.select(i);renderTray();}
function art(t){return F.TOWERS[t.type].id+'-'+F.variant(t)+'.webp';}
function statHTML(t){const s=F.stats(t);return `<strong>傷害 ${Math.round(s.damage)}${s.splash?' · 範圍':''}</strong>每秒 ${(1/s.interval).toFixed(2)} 次 · 射程 ${(s.range/70).toFixed(1)}`;}
function doBuild(){const r=game().build(selected,buildType);if(!r.ok)return toast(r.reason);sound('upgrade');buildType=-1;scene.process();renderTray();}
function doUpgrade(branch){const t=game().towers.find(t=>t.pad===selected);if(!t)return;const r=game().upgrade(t,branch);if(!r.ok)return toast(r.reason);sound('upgrade');scene.process();renderTray();}
function renderTray(){if(selected<0)return;const g=game(),t=g.towers.find(t=>t.pad===selected);$('tray').hidden=false;document.body.classList.add('tray-open');const box=$('trayContent');if(!t&&buildType<0){box.innerHTML=`<span class="tray-caption">選擇你的守護夥伴<br><b>${g.towers.length} / 6 座</b></span>`+F.TOWERS.map((d,i)=>`<button class="shop" data-shop="${i}" aria-label="${d.name}，${d.cost}金幣"><img src="assets/${d.id}-0.webp" alt="${d.name}"></button>`).join('');box.querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>{buildType=+b.dataset.shop;scene.drawRange(buildType);renderTray();});return;}
if(!t){const d=F.TOWERS[buildType],temp={type:buildType,level:1,branch:-1};box.innerHTML=`<img class="tower-portrait" src="assets/${d.id}-0.webp" alt=""><div class="tower-title"><b>${d.name}</b><small>確認射程後建造</small></div><div class="stats">${statHTML(temp)}</div><button id="confirmBuild" class="tray-action primary">建造<small>◉ ${d.cost}</small></button><button id="backShop" class="tray-action">返回</button>`;$('confirmBuild').onclick=doBuild;$('backShop').onclick=()=>{buildType=-1;scene.drawRange();renderTray();};const reason=g.reason(selected,buildType);if(reason){$('confirmBuild').classList.remove('primary');$('confirmBuild').innerHTML=`${reason.startsWith('金幣')?'金幣不足':'無法建造'}<small>${reason}</small>`;}return;}
const name=formNames[t.type][F.variant(t)],cost=F.upgradeCost(t);let actions='';if(t.level===1){actions=`<div class="branch-choice">${F.TOWERS[t.type].branches.map((name,i)=>`<button class="tray-action ${i===0?'primary':''}" data-branch="${i}">${name}<small>升至 Lv.2 · ◉ ${cost}</small></button>`).join('')}</div>`;}else if(t.level<5){const r=g.upgradeReason(t);actions=`<button id="upgradeTower" class="tray-action ${r?'':'primary'}">${r?'金幣不足':t.level===4?'最終進化':'升至 Lv.'+(t.level+1)}<small>${r||'◉ '+cost}</small></button>`;}else actions='<span class="tray-caption"><b>✦ 最終型態</b><br>已達最高等級</span>';
box.innerHTML=`<img class="tower-portrait" src="assets/${art(t)}" alt=""><div class="tower-title"><b>${name}</b><small>Lv.${t.level} / 5</small></div><div class="stats">${statHTML(t)}</div>${actions}<button id="towerDetails" class="tray-action tray-info" aria-label="查看守護塔詳細能力">ⓘ</button><button id="sellTower" class="tray-action danger">拆除<small>返還 ◉ ${Math.floor(t.spent*.7)}</small></button>`;box.querySelectorAll('[data-branch]').forEach(b=>b.onclick=()=>doUpgrade(+b.dataset.branch));if($('upgradeTower'))$('upgradeTower').onclick=()=>doUpgrade();$('towerDetails').onclick=()=>details(t);$('sellTower').onclick=()=>{g.sell(t);scene.process();buildType=-1;scene.drawRange();renderTray();};}
function details(t){const s=F.stats(t);open(formNames[t.type][F.variant(t)],`<p>${F.TOWERS[t.type].desc}</p><div class="menu-grid"><div>傷害 <b>${Math.round(s.damage)}</b></div><div>攻速 <b>${(1/s.interval).toFixed(2)} 次／秒</b></div><div>射程 <b>${(s.range/70).toFixed(1)}</b></div><div>${t.type?'爆炸半徑 <b>'+Math.round(s.splash)+'</b>':'目標 <b>'+(t.branch===1?'最高血量':'最前方')+'</b>'}</div></div>${s.burn?'<p>命中後每秒灼燒 '+s.burn+' 傷害，持續 3 秒。</p>':''}<p class="muted">射程以平台中心計算，圓圈與實際攻擊共用同一組數值。</p>`,'detail');}
function layout(){if(!scene)return;F.PADS.forEach(([x,y],i)=>{const b=$("pad"+i);if(!b)return;const t=game().towers.find(t=>t.pad===i);b.style.left=(scene.world.x+x*scene.worldScale)+"px";b.style.top=(scene.world.y+(y-18)*scene.worldScale)+"px";b.style.width=Math.max(44,100*scene.worldScale)+"px";b.style.height=Math.max(44,88*scene.worldScale)+"px";b.setAttribute("aria-label",t?"選取"+formNames[t.type][F.variant(t)]+"，第"+(i+1)+"平台":"第"+(i+1)+"建塔平台");});}
function hud(){if(!scene)return;const g=game();$('health').textContent=g.hp;$('gold').textContent=g.gold;$('wave').textContent=g.wave;$('speedBtn').textContent=g.speed+'×';$('autoBtn').checked=g.auto;const next=Math.min(g.wave+1,F.WAVES.length);$('waveBtn').innerHTML=g.phase==='combat'?`第 ${g.wave} 波進行中`:`開始第 ${next} 波 <span>▸</span>`;$('waveBtn').disabled=g.phase!=='prep';if(selected>=0)renderTray();layout();}
function frame(){if(!scene.playing)return;const g=game();let text=manualPause?'Ⅱ 已暫停 · 仍可建造、升級與拆除':g.phase==='combat'?`防守中 · ${g.enemies.length} 隻敵人在林間前進`:g.countdown>0&&g.auto?`下一波將於 ${Math.max(1,Math.ceil(g.countdown))} 秒後開始`:'準備階段 · 點選石台召喚守護塔';if($('status').textContent!==text)$('status').textContent=text;}
function preview(){const n=Math.min(game().wave,F.WAVES.length-1),w=F.WAVES[n],summary=w.map(([type,count])=>`<div>${F.ENEMIES[type].name}<b> × ${count}</b></div>`).join('');open('第 '+(n+1)+' 波 · 怪物預告',`<div class="menu-grid">${summary}</div><p class="muted">${w.some(x=>x[0]===2)?'岩甲獸血量較高，可搭配狙擊塔集中火力。':w.some(x=>x[0]===1)?'疾風菇菇移動很快，連射塔能更快補刀。':'史萊姆沿道路前進，試著用火焰塔處理聚集的敵人。'}</p>`,'preview');}
function menu(){const g=game();open('林間歇一會',`<div class="menu-grid"><div>本場擊敗 <b>${g.kills}</b></div><div>守護塔 <b>${g.towers.length} / 6</b></div><div>防守波次 <b>${g.wave} / 8</b></div><div>城堡生命 <b>${g.hp} / 20</b></div></div><div class="modal-actions"><button id="resume" class="primary">繼續守護 ▸</button><button id="restart">重新開始</button><button id="goHome">主畫面</button></div><div class="modal-actions"><button id="menuGallery">守護塔圖鑑</button><button id="menuHelp">玩法說明</button><button id="menuSound">音效：${soundOn?'開啟':'關閉'}</button></div>`,'menu');$('resume').onclick=()=>{manualPause=false;close();};$('restart').onclick=confirmRestart;$('goHome').onclick=home;$('menuGallery').onclick=()=>gallery(0);$('menuHelp').onclick=help;$('menuSound').onclick=()=>{toggleSound();menu();};}
function confirmRestart(){open('重新開始這片森林？','<p>本場的守護塔與金幣將重置，可以重新安排你的防線。</p><div class="modal-actions"><button id="cancelRestart">繼續本場</button><button id="yesRestart" class="primary">重新開始</button></div>','confirm');$('cancelRestart').onclick=close;$('yesRestart').onclick=()=>start(true);}
function help(){open('一點魔法，就能開始',`<div class="help-grid"><article><strong>① 點選石台</strong><p>先點戰場上的「＋」，再點塔的縮圖，查看費用與能力。</p></article><article><strong>② 確認射程後建造</strong><p>金色圓圈就是實際攻擊範圍。本場最多同時 6 座塔。</p></article><article><strong>③ 選擇進化方向</strong><p>弓箭：連射／狙擊。火焰：爆炎／灼燒。Lv.5 變為最終造型。</p></article><article><strong>④ 守住 8 波敵人</strong><p>可隨時建造、升級與拆除。暫停時也能安排防線。</p></article></div><p class="muted">這是一關獨立重製試玩，兩種塔皆可使用，不讀寫正式版紀錄。數值為本關試玩設定，完整平衡更新尚未套用。</p>`,'help');}
function gallery(type=0,form=0){const d=F.TOWERS[type];open('守護塔圖鑑',`<div class="gallery-tabs">${F.TOWERS.map((t,i)=>`<button data-gallery="${i}" class="${i===type?'primary':''}">${t.name}</button>`).join('')}</div><div class="gallery-forms">${formNames[type].map((n,i)=>`<button data-form="${i}" class="${form===i?'active':''}"><img src="assets/${d.id}-${i}.webp" alt="${n}"><span>${n}</span></button>`).join('')}</div><div class="gallery-detail" id="galleryDetail"></div>`,'gallery');document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>gallery(+b.dataset.gallery));document.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>galleryForm(type,+b.dataset.form));galleryForm(type,form);}
function galleryForm(type,form){const t={type,level:form===0?1:form>=3?5:2,branch:form===0?-1:(form-1)%2},s=F.stats(t);document.querySelectorAll('[data-form]').forEach(b=>b.classList.toggle('active',+b.dataset.form===form));$('galleryDetail').innerHTML=`<strong>${formNames[type][form]} · Lv.${t.level}</strong>　${form===0?'建造 ◉ '+F.TOWERS[type].cost:form>=3?'最終型態':F.TOWERS[type].branches[t.branch]+'分支'}<div class="stat-pills"><span>傷害 ${Math.round(s.damage)}</span><span>每秒 ${(1/s.interval).toFixed(2)} 次</span><span>射程 ${(s.range/70).toFixed(1)}</span>${s.splash?'<span>範圍傷害</span>':''}${s.burn?'<span>灼燒 '+s.burn+'／秒</span>':''}</div><div class="muted">${type===0?(t.branch===1?'優先攻擊血量最高的敵人，單箭傷害與射程更高。':t.branch===0?'連續快速射擊，擅長處理跑得快的敵人。':'快速攔截走在最前方的敵人。'):(t.branch===1?'火球爆開後附加持續灼燒，持續 3 秒。':t.branch===0?'提高爆炸傷害與範圍，適合密集的敵群。':'火球沿拋物線飛行，在落點造成範圍傷害。')}</div>`;}
function end(won){hideTray();const g=game(),stars=won?(g.hp===20?3:g.hp>=10?2:1):0;open(won?'森林，因你而閃耀':'休息一下，再試一次',`<div class="result-stars">${'★'.repeat(stars)+'☆'.repeat(3-stars)}</div><p class="result-summary">${won?'成功守住全部 8 波敵人！':'城堡需要你的下一次守護。'}<br>擊敗 ${g.kills} 隻敵人 · 剩餘生命 ${g.hp}</p><div class="modal-actions"><button id="playAgain" class="primary">再守護一次</button><button id="endHome">返回主畫面</button></div><p class="muted">本頁為獨立重製試玩，星星不計入正式版。</p>`,'result');$('playAgain').onclick=()=>start(true);$('endHome').onclick=home;}
function event(e){if(e.type==='state')hud();if(e.type==='wave')toast('第 '+e.wave+' 波 · 守護開始');if(e.type==='clear'&&e.wave<8)toast('第 '+e.wave+' 波完成 · 獲得 '+(35+e.wave*5)+' 金幣');if(e.type==='end')end(e.won);}
function toggleSound(){soundOn=!soundOn;$('soundBtn').textContent='音效：'+(soundOn?'開啟':'關閉');$('soundBtn').setAttribute('aria-pressed',String(soundOn));if(soundOn)sound('upgrade');}
window.UI={select,event,frame,sound,toast,layout};function ready(){scene=window.battle;$("platforms").innerHTML=F.PADS.map((p,i)=>`<button class="platform-hit" id="pad${i}" aria-label="第${i+1}建塔平台"></button>`).join("");F.PADS.forEach((p,i)=>$("pad"+i).onclick=()=>select(i));layout();pauseState();$('startBtn').onclick=()=>start(true);$('helpBtn').onclick=help;$('galleryBtn').onclick=()=>gallery();$('soundBtn').onclick=toggleSound;$('closeModal').onclick=close;$('modal').addEventListener('cancel',e=>{e.preventDefault();close();});$('closeTray').onclick=hideTray;$('pauseBtn').onclick=()=>{manualPause=!manualPause;pauseState();};$('speedBtn').onclick=()=>{game().speed=game().speed===1?2:1;hud();};$('menuBtn').onclick=menu;$('previewBtn').onclick=preview;$('waveBtn').onclick=()=>{game().startWave();scene.process();};$('autoBtn').onchange=()=>{game().auto=$('autoBtn').checked;};window.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('modal').open)close();else if(selected>=0)hideTray();else if(scene.playing)menu();}if(e.code==='Space'&&screenStack.at(-1)==='battle'&&!/INPUT|BUTTON/.test(e.target.tagName)){e.preventDefault();manualPause=!manualPause;pauseState();}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&scene.playing)manualPause=true;pauseState();});matchMedia('(orientation:portrait)').addEventListener('change',e=>{if(e.matches&&scene.playing)manualPause=true;pauseState();});}
if(window.battle)ready();else window.addEventListener('forest-ready',ready,{once:true});
})();
